={{
  (() => {
    const raw =
      $json.lead?.mobile09 ??
      $json.lead?.mobile ??
      $json.mobile ??
      $json.body?.mobile ??
      $json.query?.mobile ??
      $json.query?.from ??
      '';

    const digits = String(raw)
      .replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d))
      .replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d))
      .replace(/\D/g, '');

    const out = '0' + digits.slice(-10);
    return /^09\d{9}$/.test(out) ? out : '';
  })()
}}

