const owners = $json.ownerWeights;
const total = owners.reduce((s, o) => s + o.w, 0);

let r = Math.random() * total;
let chosen = owners[0].id;

for (const o of owners) {
  r -= o.w;
  if (r <= 0) { chosen = o.id; break; }
}

return [{ ...$json, chosenOwnerId: chosen }];

